import{c as r,Q as d,j as a,m as o}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"微服务架构","description":"","frontmatter":{"title":"微服务架构"},"headers":[],"relativePath":"综合知识/架构设计/微服务架构.md","filePath":"综合知识/架构设计/微服务架构.md","lastUpdated":null}'),e={name:"综合知识/架构设计/微服务架构.md"};function n(s,t,l,i,h,g){return d(),a("div",null,[...t[0]||(t[0]=[o('<blockquote><p>微服务架构是近年软考新增热点，主要在选择题中出现，论文也可能涉及。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 微服务核心特征</li><li>[ ] 微服务 vs SOA 对比</li><li>[ ] 服务拆分原则（DDD 限界上下文）</li><li>[ ] 关键技术：API 网关、服务注册发现、配置中心</li><li>[ ] 通信方式：同步（REST/gRPC）vs 异步（消息队列）</li><li>[ ] 容器化（Docker + Kubernetes 概念）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、微服务核心特征" tabindex="-1">一、微服务核心特征 <a class="header-anchor" href="#一、微服务核心特征" aria-label="Permalink to &quot;一、微服务核心特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>服务独立部署</strong></td><td>每个微服务可独立构建、测试、部署</td></tr><tr><td><strong>去中心化治理</strong></td><td>每个服务独立技术栈，分布式数据管理</td></tr><tr><td><strong>轻量级通信</strong></td><td>REST/gRPC/消息队列，无中心化 ESB</td></tr><tr><td><strong>容错设计</strong></td><td>熔断器、降级、超时重试</td></tr><tr><td><strong>围绕业务能力组织</strong></td><td>每个微服务对应一个业务能力</td></tr></tbody></table><h3 id="二、微服务-vs-soa-高频考点" tabindex="-1">二、微服务 vs SOA（高频考点） <a class="header-anchor" href="#二、微服务-vs-soa-高频考点" aria-label="Permalink to &quot;二、微服务 vs SOA（高频考点）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>微服务</th><th>SOA</th></tr></thead><tbody><tr><td><strong>治理</strong></td><td><strong>去中心化</strong></td><td><strong>集中式</strong>（ESB）</td></tr><tr><td><strong>服务粒度</strong></td><td>细粒度</td><td>粗粒度</td></tr><tr><td><strong>通信</strong></td><td>轻量级协议（REST）</td><td>企业服务总线（ESB）</td></tr><tr><td><strong>数据管理</strong></td><td>每服务独立数据库</td><td>共享数据库</td></tr><tr><td><strong>部署</strong></td><td>独立部署</td><td>整体部署</td></tr></tbody></table><blockquote><p>🎯 微服务架构采用<strong>去中心化管理</strong>，SOA 采用<strong>集中式管理</strong>（依赖 ESB 进行服务协调）。</p></blockquote><h3 id="三、关键技术组件" tabindex="-1">三、关键技术组件 <a class="header-anchor" href="#三、关键技术组件" aria-label="Permalink to &quot;三、关键技术组件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>用途</th><th>常用实现</th></tr></thead><tbody><tr><td><strong>API 网关</strong></td><td>统一入口，路由、鉴权、限流</td><td>Zuul, Spring Cloud Gateway</td></tr><tr><td><strong>服务注册发现</strong></td><td>服务实例动态注册与发现</td><td>Eureka, Nacos, Consul</td></tr><tr><td><strong>配置中心</strong></td><td>集中管理配置，动态刷新</td><td>Nacos, Apollo</td></tr><tr><td><strong>熔断器</strong></td><td>防止级联故障</td><td>Hystrix, Resilience4j</td></tr><tr><td><strong>负载均衡</strong></td><td>客户端负载，服务端负载</td><td>Ribbon, Nginx</td></tr></tbody></table><h3 id="四、服务拆分原则" tabindex="-1">四、服务拆分原则 <a class="header-anchor" href="#四、服务拆分原则" aria-label="Permalink to &quot;四、服务拆分原则&quot;">​</a></h3><ol><li><strong>DDD 限界上下文</strong>：以业务领域边界划分</li><li><strong>垂直拆分</strong>：按业务能力拆分</li><li><strong>水平拆分</strong>：同类功能按实例分摊</li><li>高内聚、低耦合：一个服务一个独立业务功能</li></ol><h3 id="五、通信方式" tabindex="-1">五、通信方式 <a class="header-anchor" href="#五、通信方式" aria-label="Permalink to &quot;五、通信方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>类型</th><th>典型技术</th></tr></thead><tbody><tr><td>REST API</td><td>同步</td><td>HTTP/JSON</td></tr><tr><td>gRPC</td><td>同步</td><td>Protobuf</td></tr><tr><td>消息队列</td><td><strong>异步</strong></td><td>Kafka, RabbitMQ</td></tr></tbody></table><h3 id="六、容器化" tabindex="-1">六、容器化 <a class="header-anchor" href="#六、容器化" aria-label="Permalink to &quot;六、容器化&quot;">​</a></h3><ul><li><strong>Docker</strong>：容器引擎，提供轻量级虚拟化</li><li><strong>Kubernetes</strong>（K8s）：容器编排平台，管理 Pod、Service、Deployment</li><li><strong>不可变基础设施</strong>：不修改运行中的容器，以新版本替换</li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>待补充。</p>',19)])])}const u=r(e,[["render",n]]);export{c as __pageData,u as default};
